import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.Interact{ActionType: packet.InteractActionMouseOverEntity,
#   TargetEntityRuntimeID: 300, Position: protocol.Option(mgl32.Vec3{1, 2, 3})}
WITH_POSITION = bytes.fromhex("04ac02010000803f0000004000004040")

# generated by gophertunnel b8bd735:
# &packet.Interact{ActionType: packet.InteractActionOpenInventory, TargetEntityRuntimeID: 0}
WITHOUT_POSITION = bytes.fromhex("060000")

GOLDENS = [
    pytest.param(
        v2225.InteractPacket(
            action=v2225.InteractPacket.Action.INTERACT_UPDATE,
            target_id=300,
            pos=v2225.Vec3(x=1.0, y=2.0, z=3.0),
        ),
        WITH_POSITION,
        id="with-position",
    ),
    pytest.param(
        v2225.InteractPacket(action=v2225.InteractPacket.Action.OPEN_INVENTORY, target_id=0, pos=None),
        WITHOUT_POSITION,
        id="without-position",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_interact_is_packet_33(version):
    assert version.PACKETS[33] is version.InteractPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_interact_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_interact_decodes_from_its_golden(packet, golden):
    assert v2225.InteractPacket.from_bytes(golden) == packet
